/**
 * Tray icons, generated rather than shipped (issue #371).
 *
 * The issue asks for a status indicator — "green checkmark or red alert" — in
 * the system tray. The obvious implementation is five PNGs per platform at two
 * densities, which is twenty binary files in a repository whose every other
 * asset is text, reviewed by nobody and regenerated by hand whenever the shade
 * of green changes.
 *
 * These are SVG instead, built as strings and handed to
 * `nativeImage.createFromDataURL`. The icon is a flat glyph on a transparent
 * background at a size where antialiasing is the only detail that matters, so
 * SVG loses nothing and gains a diff a reviewer can read.
 *
 * No `electron` import: these are strings, which keeps them testable and keeps
 * the colour decisions in one readable place.
 *
 * On the colours: the error state is not distinguishable from the ok state by
 * hue alone, because roughly one man in twelve cannot reliably tell this green
 * from this red. The glyphs differ in *shape* too — a check, a bordered
 * exclamation, a dot — so the state is legible without colour vision, and the
 * tooltip states it in words regardless.
 */
import type { TrayState } from './status.js';

/** The palette, as hex, one entry per state. */
export const TRAY_COLORS: Readonly<Record<TrayState, string>> = {
  // Green: everything watched is clean.
  ok: '#1f9d55',
  // Amber: warnings only, which do not fail a build.
  warning: '#c98a04',
  // Red: at least one error, or a file that will not parse.
  error: '#d13438',
  // Grey: watching nothing yet.
  idle: '#8b909a',
  // Blue: a scan is in flight.
  scanning: '#2b6cb0',
};

/** Rendered size in logical pixels. Tray glyphs are square. */
export const TRAY_ICON_SIZE = 22;

/** The SVG path for each state's glyph, on a 22×22 canvas. */
function glyphFor(state: TrayState): string {
  switch (state) {
    case 'ok':
      // A check mark.
      return '<path d="M6 11.6 9.4 15 16 7.6" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>';
    case 'error':
      // An exclamation mark inside a ring: shape alone says "problem".
      return (
        '<circle cx="11" cy="11" r="8" fill="none" stroke="currentColor" stroke-width="2"/>' +
        '<path d="M11 6.6v6.2" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/>' +
        '<circle cx="11" cy="16.1" r="1.3" fill="currentColor"/>'
      );
    case 'warning':
      // A triangle, the conventional "caution" outline.
      return (
        '<path d="M11 4.2 19 17.6H3Z" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"/>' +
        '<path d="M11 9v3.6" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round"/>' +
        '<circle cx="11" cy="15.3" r="1.1" fill="currentColor"/>'
      );
    case 'scanning':
      // A three-quarter arc, read as "in progress" even without animation.
      return '<path d="M11 3.4a7.6 7.6 0 1 1-7.3 5.5" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/>';
    case 'idle':
      // A hollow dot: present, watching nothing.
      return '<circle cx="11" cy="11" r="6.4" fill="none" stroke="currentColor" stroke-width="2"/>';
  }
}

/**
 * The SVG markup for one tray state.
 *
 * `monochrome` renders the glyph in black so macOS can treat it as a template
 * image and recolour it for light, dark, and highlighted menu bars. Colour is
 * carried by the tooltip and the menu in that mode — a template image that
 * ignored the OS would look wrong in half of them.
 */
export function traySvg(state: TrayState, monochrome = false): string {
  const color = monochrome ? '#000000' : TRAY_COLORS[state];
  return (
    `<svg xmlns="http://www.w3.org/2000/svg" width="${TRAY_ICON_SIZE}" ` +
    `height="${TRAY_ICON_SIZE}" viewBox="0 0 22 22" color="${color}">` +
    `${glyphFor(state)}</svg>`
  );
}

/**
 * The same markup as a `data:` URL, which is what `nativeImage` takes.
 *
 * Base64 rather than percent-encoding, because `nativeImage
 * .createFromDataURL` is stricter about the latter than browsers are.
 */
export function trayIconDataUrl(state: TrayState, monochrome = false): string {
  const svg = traySvg(state, monochrome);
  return `data:image/svg+xml;base64,${Buffer.from(svg, 'utf8').toString('base64')}`;
}

/**
 * A one-line label for the tray menu's status row.
 *
 * Says the state in words, so the icon's colour is never the only carrier of
 * the information.
 */
export function trayStateLabel(state: TrayState): string {
  switch (state) {
    case 'ok':
      return 'No problems';
    case 'warning':
      return 'Warnings only';
    case 'error':
      return 'Errors found';
    case 'scanning':
      return 'Scanning…';
    case 'idle':
      return 'Not watching a folder';
  }
}
